-- Run in: Supabase Dashboard -> SQL Editor -> New Query
-- ============================================================
--
-- Source: the "Glavna" sheet only (2077 rows total incl. header/legend
-- rows; real header is row 6, data from row 7 on -- rows 1-5 are a
-- service-type legend/ownership annotation block, not data). No
-- merged cells in this sheet -- one row per field, no forward-fill
-- needed (unlike Vzorčenje vzorcev2026.xlsx / OSTANKI).
--
-- field_size_ha: 7 rows had it as text with a stray space + comma
-- decimal ("0 ,93  ") instead of a plain number -- cleaned to numeric
-- during extraction, value preserved exactly (e.g. 0.93).
--
-- Purpose: 162 of the 186 GERK codes from vzorcenje_uvoz_2026 that had
-- no match in the fields registry DO match this sheet's Field ID --
-- meant as a second-choice Ha source (fields registry first, this as
-- fallback), same two-tier pattern WorkTracker itself uses (registry,
-- then imported-zone geometry) -- see get_work_orders_center_points-
-- style reasoning discussed this session.
--
-- RLS is enabled with no policies (service_role/dashboard only) --
-- raw staging import, no defined access model yet. Also captures
-- email/company/name/surname for potential future customer matching,
-- per the user's request, though that wasn't the focus of this pass.

create table public.glavna_tabela_2026 (
    id              uuid primary key default gen_random_uuid(),
    customer_no     text,
    email           text,
    company         text,
    name            text,
    surname         text,
    field_location  text,
    field_id        text,
    field_size_ha   numeric,
    field_name      text,
    created_at      timestamptz not null default now()
);

alter table public.glavna_tabela_2026 enable row level security;

